import React, { useEffect } from 'react';
import AnimatedBackground from '../components/AnimatedBackground.jsx';
import HexagonPulseBackground from '../components/HexagonPulseBackground';
import { Link } from 'react-router-dom';
import img1 from '../assets/highlight1.png';
import img2 from '../assets/highlight2.png';
import img3 from '../assets/highlight3.png';
import img4 from '../assets/highlight4.png';
import img5 from '../assets/highlight5.png';

export default function Invisalign() {
  useEffect(() => {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add('is-visible');
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);

  return (
    <div className="relative min-h-screen bg-white overflow-x-hidden">
      {/* layered animated backdrops for continuity */}
      <div className="absolute inset-0 -z-30 opacity-95 pointer-events-none" aria-hidden>
        <AnimatedBackground />
      </div>
      <div className="absolute inset-0 -z-20 pointer-events-none" aria-hidden>
        <HexagonPulseBackground />
      </div>

      <header className="relative max-w-6xl mx-auto px-6 py-20 text-center">
        <div className="relative inline-block w-full bg-white/70 backdrop-blur-md rounded-3xl px-8 py-8 shadow-2xl overflow-visible">
          <h1 className="text-3xl md:text-4xl font-extrabold text-sky-800 mb-3">Invisalign — Clear Aligners for a Confident Smile</h1>
          <p className="text-gray-700 max-w-3xl mx-auto mb-6">A discreet, removable orthodontic system that uses a sequence of clear aligners to gradually move teeth into the desired position — ideal for adults and teens seeking straightening without traditional braces.</p>

          <div className="flex justify-center gap-4 mb-6">
            <Link to="/book-online" className="inline-block">
              <button className="px-6 py-2 rounded-full bg-sky-600 text-white font-semibold shadow hover:scale-105 transition">Book a Scan</button>
            </Link>
            <a href="#gallery" className="px-6 py-2 rounded-full border border-sky-600 text-sky-600 font-semibold hover:bg-sky-50 transition">See Cases</a>
          </div>

          {/* dotted treatment path accent (SVG) */}
          <div className="mt-4 flex justify-center pointer-events-none aria-hidden">
            <svg className="w-80 h-28" viewBox="0 0 400 120" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
              <path className="dot-path" d="M10 90 C100 10, 300 10, 390 90" stroke="#60a5fa" strokeWidth="3" strokeLinecap="round" strokeDasharray="6 8" />
              <circle className="dot-move" r="6" cx="10" cy="90" fill="#2563eb" />
            </svg>
          </div>
        </div>
      </header>

      <section id="gallery" className="max-w-6xl mx-auto px-6 py-12">
        <h2 className="text-2xl md:text-3xl font-bold text-sky-800 mb-6 text-center reveal">Real Patient Progress</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {[img1, img2, img3, img4, img5].map((src, idx) => (
            <figure key={idx} className="reveal rounded-xl overflow-hidden shadow-lg transform transition hover:-translate-y-2" style={{ ['--delay']: `${idx * 100}ms` }}>
              <img src={src} alt={`invisalign-case-${idx+1}`} className="w-full h-56 object-cover" />
              <figcaption className="p-4 bg-white">
                <p className="text-sm text-gray-600">Case {idx + 1} — progress examples of staged clear aligner treatment.</p>
              </figcaption>
            </figure>
          ))}
        </div>
      </section>

      <section className="w-full px-6 md:px-12 py-12 bg-white">
        <div className="max-w-screen-xl mx-auto">
          <h3 className="text-2xl md:text-3xl font-bold text-sky-800 mb-4 text-center reveal">About Invisalign treatment</h3>
          <article className="text-gray-700 leading-relaxed text-lg reveal" style={{ textAlign: 'justify' }}>
            Clear aligner therapy has transformed how we approach minor to moderate tooth movement. Instead of fixed metal braces, a patient receives a series of transparent, removable aligners designed with precision to apply gentle, controlled forces. Each aligner is worn for about one to two weeks before progressing to the next, allowing the teeth to move incrementally toward the final planned positions. This staged approach is comfortable and predictable when guided by clinical expertise and modern digital planning.

            Treatment begins with a comprehensive assessment — photos, digital scans or impressions, and a clinical exam to evaluate periodontal health, existing restorations, and skeletal relationships. Using the scan data we create a digital setup that shows the planned tooth movements, expected timeline, and any auxiliaries required (attachments, interproximal reduction). We discuss realistic outcomes and functional goals so patients understand what to expect at each stage.

            One of the major advantages of aligners is aesthetics and hygiene: patients can remove them to brush, floss, and for important events. Compliance is important — wearing aligners typically 20–22 hours per day is necessary for efficient progress. We support patients with remote monitoring options and scheduled visits to track fit, comfort, and progress. Minor refinements or additional aligners can be prescribed if small corrections are needed after the initial sequence.

            For complex movements or severe bite discrepancies, aligners are often combined with auxiliary treatments or used after orthodontic-assisted surgical or restorative work. Aligners integrate well with restorative planning since final tooth positions can be staged to favor future crowns, veneers, or implant work when required. Our clinicians tailor the biomechanics to each patient’s biology, making choices that reduce unnecessary tooth reduction and prioritize long-term periodontal health.

            If you are considering a discreet option to align your teeth, book a consultation. We’ll evaluate your bite, discuss timing, expected costs, and produce a clear visual treatment plan so you can decide confidently. Clear aligner therapy can deliver a confident smile with minimal disruption to daily life when executed by a practiced team.
          </article>
        </div>
      </section>

      <style>{`
  .reveal { opacity: 0; transform: translateY(28px) scale(0.995); will-change: transform, opacity; }
  .reveal.is-visible { animation: revealIn 700ms cubic-bezier(.22,.9,.36,1) both; }
  @keyframes revealIn { from { opacity: 0; transform: translateY(28px) scale(0.995); } to { opacity: 1; transform: translateY(0) scale(1); } }
  .reveal { animation-delay: var(--delay, 0ms); }

  /* animated dotted path accent */
  .dot-path { stroke-dasharray: 6 8; stroke-dashoffset: 0; animation: dashMove 3.6s linear infinite; opacity: 0.95; }
  .dot-move { transform-origin: center; animation: follow 3.6s linear infinite; }

  @keyframes dashMove { to { stroke-dashoffset: -28; } }
  @keyframes follow { 0% { transform: translateX(0) translateY(0); } 50% { transform: translateX(280px) translateY(-58px); } 100% { transform: translateX(0) translateY(0); } }

  header .backdrop-blur-md { backdrop-filter: blur(6px); }
  `}</style>
    </div>
  );
}
